import { SignedDataVerifier, Environment, type JWSTransactionDecodedPayload } from "@apple/app-store-server-library";

const BUNDLE_ID = "com.qrmingle.app";

// Apple's public root CA certificates (DER, base64-encoded), downloaded from
// https://www.apple.com/certificateauthority/ — embedded directly rather than read from a
// file on disk, since the production server runs from a single esbuild-bundled file with no
// asset-copying step, and this project's ESM output has no reliable __dirname to resolve from.
const APPLE_ROOT_CA_G3_B64 =
  "";

const APPLE_ROOT_CA_G2_B64 =
  "";

const rootCertificates = [
  Buffer.from(APPLE_ROOT_CA_G3_B64, "base64"),
  Buffer.from(APPLE_ROOT_CA_G2_B64, "base64"),
];

// The App Store Connect "Apple ID" (a numeric app identifier, not the bundle ID) —
// required by Apple's library for Production verification, optional for Sandbox.
// Find it in App Store Connect > App Information > General Information > Apple ID.
const appAppleId = process.env.APPLE_APP_STORE_ID ? Number(process.env.APPLE_APP_STORE_ID) : undefined;

const sandboxVerifier = new SignedDataVerifier(rootCertificates, true, Environment.SANDBOX, BUNDLE_ID);

// Null until APPLE_APP_STORE_ID is set — until then, real production purchases cannot be
// verified (only TestFlight/sandbox ones can). Set this env var before going live with real IAP.
const productionVerifier = appAppleId
  ? new SignedDataVerifier(rootCertificates, true, Environment.PRODUCTION, BUNDLE_ID, appAppleId)
  : null;

if (!productionVerifier) {
  console.warn(
    "[apple-iap] APPLE_APP_STORE_ID is not set — production App Store purchases cannot be verified yet, only TestFlight/sandbox ones."
  );
}

// Verifies the cryptographic signature chain of a StoreKit 2 transaction JWS against Apple's
// root certificates (not just decoding the payload, which anyone could forge). Tries Production
// first, then falls back to Sandbox, since both real customers and TestFlight testers hit this
// same endpoint and the two environments sign with different keys.
export async function verifyStoreKitTransaction(jwsRepresentation: string): Promise<JWSTransactionDecodedPayload> {
  if (productionVerifier) {
    try {
      return await productionVerifier.verifyAndDecodeTransaction(jwsRepresentation);
    } catch {
      // Falls through to sandbox — TestFlight/sandbox transactions are expected to fail Production verification.
    }
  }
  return await sandboxVerifier.verifyAndDecodeTransaction(jwsRepresentation);
}
